#include "guards.h"
#include "fonts.h"  // generated by tools/ttf2gfx.py at 4x size
#include "smooth.h"

static const uint16_t GOLD_L = RGB565(251, 224, 138);
static const uint16_t GOLD = RGB565(232, 184, 74);
static const uint16_t GOLD_D = RGB565(168, 122, 30);
static const uint16_t RED = RGB565(214, 40, 40);
static const uint16_t GREEN = RGB565(58, 165, 72);
static const uint16_t GREEN_D = RGB565(29, 107, 42);
static const uint16_t INK = RGB565(18, 18, 18);
static const uint16_t PAPER = RGB565(250, 250, 250);

// Text styles shared by every design, so lettering looks the same across guards. The serif is
// only used large enough for its thin strokes to stay sharp; everything small is the bold sans.
struct TextStyle {
  const GFXfont *font;
  float scale, spacing;  // spacing: extra px between letters on ring text
};
static const TextStyle BAND = {&TitleFont4x, 0.25f, 2.5f};       // ring and banner text
static const TextStyle BAND_LONG = {&TitleFont4x, 0.2f, 1.5f};   // ring text too long for BAND
static const TextStyle HEADLINE = {&PokerFont4x, 0.25f, 0};      // big centre word
static const TextStyle LABEL = {&PokerFont4x, 0.2f, 0};         // centre captions
static const TextStyle CARD_INDEX = {&TitleFont4x, 0.17f, 0};    // corner rank on court cards
static const TextStyle CARD_RANK = {&TitleFont4x, 0.3f, 0};      // big rank on number cards
static const TextStyle ALERT = {&TitleFont4x, 0.42f, 0};         // short warning words across the centre
static const TextStyle BIG_NUMBER = {&TitleFont4x, 0.6f, 0};     // lone number filling the centre

static void text(Smooth &s, const TextStyle &t, const char *str, float x, float y, uint16_t c) {
  s.text(t.font, t.scale, str, x, y, c);
}
// extra: additional letter spacing for designs that space their ring text out.
static void ringText(Smooth &s, const TextStyle &t, const char *str, float r, bool bottom, uint16_t c, float extra = 0) {
  s.arcText(t.font, t.scale, str, r, bottom ? 90 : -90, t.spacing + extra, c, bottom);
}

// Maps shape-local offsets to the screen: centred on (x, y), scaled by k, rotated by deg.
struct Place {
  float x0, y0, k, co, sn;
  Place(float x, float y, float k, float deg) : x0(x), y0(y), k(k), co(cosf(deg * DEG_TO_RAD)), sn(sinf(deg * DEG_TO_RAD)) {}
  float x(float dx, float dy) const { return x0 + (dx * co - dy * sn) * k; }
  float y(float dx, float dy) const { return y0 + (dx * sn + dy * co) * k; }
};

// Card suits about 18px tall times k, centred on (x, y), rotated by deg.
static void spade(Smooth &s, float x, float y, uint16_t c, float k = 1, float deg = 0) {
  Place p(x, y, k, deg);
  s.tri(p.x(-7.6f, 0.5f), p.y(-7.6f, 0.5f), p.x(7.6f, 0.5f), p.y(7.6f, 0.5f), p.x(0, -9), p.y(0, -9), c);
  s.circle(p.x(-4, 2), p.y(-4, 2), 4.2f * k, c);
  s.circle(p.x(4, 2), p.y(4, 2), 4.2f * k, c);
  s.tri(p.x(0, 2), p.y(0, 2), p.x(-3, 9), p.y(-3, 9), p.x(3, 9), p.y(3, 9), c);
}
static void heart(Smooth &s, float x, float y, uint16_t c, float k = 1, float deg = 0) {
  Place p(x, y, k, deg);
  s.circle(p.x(-4.2f, -3.5f), p.y(-4.2f, -3.5f), 4.8f * k, c);
  s.circle(p.x(4.2f, -3.5f), p.y(4.2f, -3.5f), 4.8f * k, c);
  s.tri(p.x(-8.8f, -2), p.y(-8.8f, -2), p.x(8.8f, -2), p.y(8.8f, -2), p.x(0, 8.5f), p.y(0, 8.5f), c);
}
static void club(Smooth &s, float x, float y, uint16_t c, float k = 1, float deg = 0) {
  Place p(x, y, k, deg);
  s.circle(p.x(0, -4.5f), p.y(0, -4.5f), 4 * k, c);
  s.circle(p.x(-4.6f, 1.5f), p.y(-4.6f, 1.5f), 4 * k, c);
  s.circle(p.x(4.6f, 1.5f), p.y(4.6f, 1.5f), 4 * k, c);
  s.circle(x, y, 2.5f * k, c);  // fills the gap where the three lobes meet
  s.tri(x, y, p.x(-3, 9), p.y(-3, 9), p.x(3, 9), p.y(3, 9), c);
}
static void diamond(Smooth &s, float x, float y, uint16_t c, float k = 1, float deg = 0) {
  Place p(x, y, k, deg);
  float q[] = {p.x(0, -9), p.y(0, -9), p.x(7, 0), p.y(7, 0), p.x(0, 9), p.y(0, 9), p.x(-7, 0), p.y(-7, 0)};
  s.poly(q, 4, c);
}

static void chipLeaderScene(Smooth &s) {
  s.fill(RGB565_BLACK);
  s.circle(120, 120, 119.5f, GOLD_L, GOLD_D, 113);  // holes: inner circles cover the middle
  s.circle(120, 120, 113, INK, INK, 84);
  s.circle(120, 120, 84, GOLD_L, GOLD_D, 81);
  s.circle(120, 120, 81, PAPER);

  s.clip(81);  // stripes stay inside the white face
  s.rect(0, 86, 240, 24, RED);
  s.rect(0, 126, 240, 22, INK);
  s.clip(0);

  float outline[] = {73.5f, 105.5f, 166.5f, 105.5f, 166.5f, 139, 120, 183.5f, 73.5f, 139};
  float body[] = {78.5f, 110.5f, 161.5f, 110.5f, 161.5f, 137, 120, 176.5f, 78.5f, 137};
  s.poly(outline, 5, INK);
  s.poly(body, 5, PAPER);
  s.tri(92, 142, 148, 142, 120, 168, RED);

  s.rect(67, 83, 106, 32, GOLD);
  s.rect(69.5f, 85.5f, 101, 27, RED);
  text(s, HEADLINE, "POKER", 120, 99, GOLD);

  spade(s, 84, 66, INK);
  heart(s, 108, 66, RED);
  club(s, 132, 66, INK);
  diamond(s, 156, 66, RED);

  ringText(s, BAND, "THE CHIP LEADER", 97, false, GOLD);

  // Laurel branches around the bottom, gold spade at the base.
  for (int side = 1; side >= -1; side -= 2) {
    float a0 = side == 1 ? 28 : 152, a1 = side == 1 ? 80 : 100;
    s.arc(120, 120, 99, 1.6f, min(a0, a1), max(a0, a1), GREEN_D);
    for (int k = 0; k < 6; k++) {
      float a = a0 + (a1 - a0) * (k + 0.5f) / 6;
      for (int off = -1; off <= 1; off += 2) {
        float r = 99 + off * 6, t = a * DEG_TO_RAD;
        s.ellipse(120 + r * cosf(t), 120 + r * sinf(t), 7.5f, 3.2f, a - 90 * side + off * 35 * side, GREEN);
      }
    }
  }
  spade(s, 120, 217, GOLD);
}

static void chipLeader(Arduino_GFX *gfx) { smoothDraw(gfx, chipLeaderScene); }

static const uint16_t CREAM = RGB565(244, 238, 222);
static const uint16_t DUCK = RGB565(250, 204, 60);
static const uint16_t DUCK_D = RGB565(196, 132, 20);
static const uint16_t BEAK = RGB565(240, 124, 24);

// A cartoon duck facing left, body centred on (x, y), about 44 x 36 px.
// Drawn twice: a slightly grown dark pass for the outline, then the fill.
static void duck(Smooth &s, float x, float y, float k) {
  for (int pass = 0; pass < 2; pass++) {
    float g = pass ? 0 : 1.3f;
    uint16_t c = pass ? DUCK : DUCK_D;
    s.tri(x + 12 * k - g, y + 2 * k + g, x + 23 * k + g, y - 7 * k - g, x + 19 * k + g, y + 9 * k + g, c);  // tail
    s.ellipse(x + 2 * k, y + 6 * k, 18 * k + g, 10.5f * k + g, -8, c);                             // body
    s.ellipse(x - 7 * k, y - 3 * k, 6 * k + g, 8 * k + g, 15, c);                                  // neck
    s.circle(x - 9 * k, y - 12 * k, 8.5f * k + g, c);                                          // head
    s.ellipse(x - 19.5f * k, y - 9.5f * k, 6.5f * k + g, 2.8f * k + g, 12, pass ? BEAK : DUCK_D);  // beak
  }
  s.ellipse(x + 5 * k, y + 4 * k, 10 * k, 5.5f * k, -18, DUCK_D);  // wing
  s.ellipse(x + 5 * k, y + 3.5f * k, 8.6f * k, 4.2f * k, -18, DUCK);
  s.circle(x - 10 * k, y - 14 * k, 2.8f * k, PAPER);  // eye
  s.circle(x - 11 * k, y - 14 * k, 1.5f * k, INK);
}

// Shared frame: gold rim, cream band with suits down each side, black banners carrying top and
// bottom text, gold rope ring, black centre (radius 73) for the design's own art.
static void bannerFrame(Smooth &s, const TextStyle &topStyle, const char *top, const TextStyle &bottomStyle,
                        const char *bottom) {
  s.fill(RGB565_BLACK);
  s.circle(120, 120, 119.5f, GOLD_L, GOLD_D, 112);
  s.circle(120, 120, 112, CREAM, CREAM, 84);

  // Black banners with gold edges across the top and bottom of the band.
  for (int b = 0; b < 2; b++) {
    float a0 = b ? 38 : -142, a1 = b ? 142 : -38;
    s.arc(120, 120, 98, 30, a0, a1, GOLD);
    s.arc(120, 120, 98, 25, a0 + 1.5f, a1 - 1.5f, INK);
  }
  ringText(s, topStyle, top, 98, false, GOLD);
  ringText(s, bottomStyle, bottom, 98, true, GOLD);

  // Suits down each side of the band: club, diamond, spade, heart from top to bottom.
  const float side[] = {-24, -8, 8, 24};
  for (int i = 0; i < 4; i++)
    for (int left = 0; left < 2; left++) {
      float a = (left ? 180 - side[i] : side[i]) * DEG_TO_RAD, x = 120 + 98 * cosf(a), y = 120 + 98 * sinf(a);
      if (i == 0) club(s, x, y, INK);
      if (i == 1) diamond(s, x, y, RED);
      if (i == 2) spade(s, x, y, INK);
      if (i == 3) heart(s, x, y, RED);
    }

  // Gold ring with a twisted-rope inner edge around the black centre.
  s.circle(120, 120, 85, GOLD_L, GOLD_D, 80);
  s.circle(120, 120, 80, GOLD_D);
  for (int i = 0; i < 48; i++) {
    float a = i * 7.5f, t = a * DEG_TO_RAD;
    s.ellipse(120 + 77 * cosf(t), 120 + 77 * sinf(t), 4.2f, 1.9f, a + 90 + 50, GOLD_L);
  }
  s.circle(120, 120, 73, INK);
}

static void ducksScene(Smooth &s) {
  bannerFrame(s, BAND, "THE DUCKS", BAND, "QUACK QUACK");
  duck(s, 90, 107.5f, 1.15f);
  duck(s, 154, 107.5f, 1.15f);
  text(s, LABEL, "POCKET 2s", 120.5f, 149.5f, GOLD);
}

static void ducks(Arduino_GFX *gfx) { smoothDraw(gfx, ducksScene); }

static const uint16_t SKIN = RGB565(248, 214, 170);
static const uint16_t HAIR = RGB565(140, 84, 36);
static const uint16_t CARD_EDGE = RGB565(110, 110, 110);

typedef void (*SuitFn)(Smooth &, float, float, uint16_t, float, float);

// A 55 x 77 court card centred on (cx, cy), rotated by deg: a top-left index plus a simple
// king (crown, beard) or jack (feathered hat) figure in a frame of the suit's colour, which takes
// the rest of the card.
static void courtCard(Smooth &s, float cx, float cy, float deg, char rank, SuitFn suit, uint16_t col) {
  Place c(cx, cy, 1.1f, deg);                                    // card space: 50 x 70 before scaling
  Place f(c.x(5, 2.7f), c.y(5, 2.7f), c.k * 1.3f, deg);  // figure space, centred in the frame
  auto quad = [&](float x0, float y0, float x1, float y1, float x2, float y2, float x3, float y3, uint16_t col) {
    float p[] = {f.x(x0, y0), f.y(x0, y0), f.x(x1, y1), f.y(x1, y1), f.x(x2, y2), f.y(x2, y2), f.x(x3, y3), f.y(x3, y3)};
    s.poly(p, 4, col);
  };
  auto tri = [&](float x0, float y0, float x1, float y1, float x2, float y2, uint16_t col) {
    s.tri(f.x(x0, y0), f.y(x0, y0), f.x(x1, y1), f.y(x1, y1), f.x(x2, y2), f.y(x2, y2), col);
  };
  auto circle = [&](float x, float y, float r, uint16_t col) { s.circle(f.x(x, y), f.y(x, y), r * f.k, col); };

  s.rrect(cx, cy, 52.5f * c.k, 72.5f * c.k, 5, deg, CARD_EDGE);
  s.rrect(cx, cy, 50 * c.k, 70 * c.k, 4, deg, PAPER);
  // Figure frame: right of the index column, 3.5 from the other edges.
  s.rrect(c.x(5, 0), c.y(5, 0), 33 * c.k, 63 * c.k, 2, deg, col);
  s.rrect(c.x(5, 0), c.y(5, 0), 30 * c.k, 60 * c.k, 1.5f, deg, PAPER);

  quad(-11, 21, 11, 21, 8, 4, -8, 4, col);  // robe with a gold sash
  quad(-2.5f, 21, 2.5f, 21, 1.5f, 4, -1.5f, 4, GOLD);
  if (rank == 'K') {
    circle(0, -1, 5.5f, HAIR);  // beard
    circle(0, -5, 5.5f, SKIN);
    quad(-6, -9, 6, -9, 6, -12.5f, -6, -12.5f, GOLD);  // crown
    tri(-6, -12.5f, -2, -12.5f, -5.5f, -18.5f, GOLD);
    tri(-2, -12.5f, 2, -12.5f, 0, -19.5f, GOLD);
    tri(2, -12.5f, 6, -12.5f, 5.5f, -18.5f, GOLD);
  } else {
    circle(-5, -6, 2.6f, HAIR);
    circle(5, -6, 2.6f, HAIR);
    circle(0, -5, 5.5f, SKIN);
    s.ellipse(f.x(0, -11), f.y(0, -11), 8 * f.k, 3.4f * f.k, deg, RED);  // hat with a feather
    tri(3, -12, 10, -20, 7, -10.5f, GOLD);
  }
  circle(-2, -5.5f, 0.9f, INK);  // eyes
  circle(2, -5.5f, 0.9f, INK);

  // Top-left index only: rank over a small suit.
  s.glyph(CARD_INDEX.font, CARD_INDEX.scale, rank, c.x(-19, -26), c.y(-19, -26), deg, col);
  suit(s, c.x(-19, -14), c.y(-19, -14), col, 0.55f, deg);
}

static void jackKingOffScene(Smooth &s) {
  bannerFrame(s, BAND, "I LOVE", BAND_LONG, "JACK KING OFF");
  courtCard(s, 96, 122, -10, 'J', spade, INK);
  courtCard(s, 144, 118, 8, 'K', heart, RED);
}

static void jackKingOff(Arduino_GFX *gfx) { smoothDraw(gfx, jackKingOffScene); }

// Five-pointed star of outer radius r: a pentagon core plus five point triangles.
static void star(Smooth &s, float x, float y, float r, uint16_t c) {
  float in[10];
  for (int i = 0; i < 5; i++) {
    float a = (-90 + 36 + 72 * i) * DEG_TO_RAD;
    in[2 * i] = x + 0.4f * r * cosf(a), in[2 * i + 1] = y + 0.4f * r * sinf(a);
  }
  s.poly(in, 5, c);
  for (int i = 0; i < 5; i++) {
    float a = (-90 + 72 * i) * DEG_TO_RAD;
    int j = (i + 4) % 5;  // inner points either side of tip i
    s.tri(x + r * cosf(a), y + r * sinf(a), in[2 * j], in[2 * j + 1], in[2 * i], in[2 * i + 1], c);
  }
}

// A 56 x 78 number card centred on (cx, cy), rotated by deg, with its rank in the top corner
// (corner = -1 left, +1 right) and the suit under it, both turned with the card.
static void pipCard(Smooth &s, float cx, float cy, float deg, char rank, int corner, SuitFn suit, uint16_t col) {
  Place p(cx, cy, 1, deg);
  s.rrect(cx, cy, 58.5f, 80.5f, 5, deg, CARD_EDGE);
  s.rrect(cx, cy, 56, 78, 4, deg, PAPER);
  float x = corner * 18;  // 4 px padding from the card edge to the 12 px wide rank, suit centred under it
  s.glyph(CARD_RANK.font, CARD_RANK.scale, rank, p.x(x, -27), p.y(x, -27), deg, col);
  suit(s, p.x(x, -8), p.y(x, -8), col, 0.95f, deg);
}

static const uint16_t BROWN = RGB565(178, 98, 46);
static const uint16_t BROWN_D = RGB565(84, 42, 18);
static const uint16_t TAN = RGB565(218, 156, 100);
static const uint16_t HOOF = RGB565(58, 34, 24);

// Grinning cartoon donkey filling the centre: ears, head, muzzle, body, two hooves at the bottom.
static void donkey(Smooth &s) {
  for (int pass = 0; pass < 2; pass++) {  // dark grown pass = outline, then fill
    float g = pass ? 0 : 1.6f;
    uint16_t c = pass ? BROWN : BROWN_D;
    float neck[] = {112 - g, 116, 128 + g, 116, 131 + g, 143, 109 - g, 143};  // starts behind the muzzle
    s.poly(neck, 4, c);
    s.ellipse(120, 155, 23 + g, 16 + g, 0, c);   // rounded chest
    s.ellipse(101, 170, 15 + g, 8.5f + g, 132, c);  // legs curving out to the hooves
    s.ellipse(139, 170, 15 + g, 8.5f + g, 48, c);
    s.ellipse(101, 57, 8 + g, 20 + g, -18, c);  // ears
    s.ellipse(139, 57, 8 + g, 20 + g, 18, c);
    s.ellipse(120, 95, 27 + g, 30 + g, 0, c);  // head
  }
  s.ellipse(101, 59, 4, 13, -18, TAN);  // inside of the ears
  s.ellipse(139, 59, 4, 13, 18, TAN);
  s.tri(109, 72, 117, 70, 106, 58, BROWN_D);  // tuft of mane
  s.tri(115, 70, 125, 70, 120, 54, BROWN_D);
  s.tri(123, 70, 131, 72, 134, 58, BROWN_D);

  for (int side = -1; side <= 1; side += 2) {
    float ex = 120 + 11 * side;
    s.ellipse(ex, 89, 9.2f, 11.2f, 0, BROWN_D);  // eyes
    s.ellipse(ex, 89, 8, 10, 0, PAPER);
    s.circle(ex - 3 * side, 92, 3.6f, INK);
  }

  s.ellipse(120, 119, 22.5f, 17.5f, 0, BROWN_D);  // muzzle
  s.ellipse(120, 119, 21, 16, 0, TAN);
  // Grin: a dark-rimmed half ellipse of teeth under a lip line, upturned corners, and the muzzle
  // showing below it as the lower lip.
  s.ellipse(120, 123, 15, 7, 0, INK);
  s.ellipse(120, 123.6f, 13.4f, 5.6f, 0, PAPER);
  s.rect(103, 114, 34, 9, TAN);
  s.rect(105, 122, 30, 1.6f, BROWN_D);
  s.ellipse(104.5f, 121, 3.4f, 1.1f, 53, BROWN_D);
  s.ellipse(135.5f, 121, 3.4f, 1.1f, -53, BROWN_D);
  s.ellipse(111, 113, 3.6f, 2.4f, -20, BROWN_D);  // nostrils
  s.ellipse(129, 113, 3.6f, 2.4f, 20, BROWN_D);

  for (int side = -1; side <= 1; side += 2) {
    float hx = 120 + 30 * side;
    // Bell-shaped hooves outlined in gold, with a shaggy dark fringe over the top and a split
    // (arch) at the bottom; drawn over the rope ring like the original.
    for (int pass = 0; pass < 3; pass++) {  // dark rim so the gold edge stands off the gold ring behind
      float g = (2 - pass) * 1.3f;
      uint16_t c = pass == 0 ? INK : pass == 1 ? GOLD : HOOF;
      s.ellipse(hx, 183, 15 + g, 11 + g, 0, c);
      s.rrect(hx, 190, 34 + 2 * g, 14 + 2 * g, 5 + g, 0, c);
    }
    for (int pass = 0; pass < 2; pass++) {
      float d = pass ? 0 : 1.3f;  // gold copy shifted down edges the fringe's hem
      uint16_t c = pass ? INK : GOLD;
      s.ellipse(hx, 179.5f + d, 14, 6.5f, 0, c);
      for (int i = 0; i < 6; i++) {
        float x = hx - 12.5f + 5 * i;
        s.tri(x - 3, 181 + d, x + 3, 181 + d, x, (i % 2 ? 187 : 189.5f) + d, c);
      }
    }
    s.rrect(hx, 193.6f, 8.2f, 8, 4.1f, 0, GOLD);  // split: a small arch open at the bottom
    s.rrect(hx, 194.6f, 5.4f, 7.4f, 2.7f, 0, INK);
  }
}

static void donkScene(Smooth &s) {
  s.fill(RGB565_BLACK);
  s.circle(120, 120, 119.5f, GOLD_L, GOLD_D, 112);
  s.circle(120, 120, 112, INK, INK, 86);
  s.circle(120, 120, 86, GOLD_D);  // rope ring
  for (int i = 0; i < 52; i++) {
    float a = i * (360.0f / 52), t = a * DEG_TO_RAD;
    s.ellipse(120 + 83.5f * cosf(t), 120 + 83.5f * sinf(t), 3.6f, 1.5f, a + 90 + 50, GOLD_L);
  }
  s.circle(120, 120, 81, GOLD_L, GOLD);

  ringText(s, BAND, "I'M A DONK", 99, false, GOLD, 5);  // spaced out like the original
  ringText(s, BAND_LONG, "SEVEN AND TWO OFFSUIT", 99, true, GOLD);
  const float side[] = {-30, -15, 0, 15};
  for (int i = 0; i < 4; i++)
    for (int left = 0; left < 2; left++) {
      float a = (left ? 180 - side[i] : side[i]) * DEG_TO_RAD;
      star(s, 120 + 99 * cosf(a), 120 + 99 * sinf(a), 6.5f, GOLD);
    }

  pipCard(s, 86, 124, -15, '7', -1, spade, INK);
  pipCard(s, 154, 124, 15, '2', 1, diamond, RED);
  donkey(s);
}

static void donk(Arduino_GFX *gfx) { smoothDraw(gfx, donkScene); }

// Shown briefly when a client asks for a guard that doesn't exist; not a guard itself.
static int noGuardN;
static void noGuardScene(Smooth &s) {
  s.fill(RGB565_BLACK);
  s.circle(120, 120, 119.5f, RED, RED, 112);
  text(s, ALERT, "NO GUARD", 120, 80, GOLD);
  char num[12];
  snprintf(num, sizeof num, "%d", noGuardN);
  text(s, BIG_NUMBER, num, 120, 140, PAPER);
}
void drawNoGuard(Arduino_GFX *gfx, int n) {
  noGuardN = n;
  smoothDraw(gfx, noGuardScene);
}

const GuardFn GUARDS[] = {chipLeader, ducks, jackKingOff, donk};
const int GUARD_COUNT = sizeof(GUARDS) / sizeof(GUARDS[0]);
